const embedding = $input.first().json.embedding;
const trigger = $('Execute Workflow Trigger').first().json;
const limit = Number(trigger.limit) || 5;
const project = (trigger.project || '').trim();

const body = {
  vector: embedding,
  limit: limit,
  with_payload: true,
  score_threshold: 0.5
};

if (project) {
  body.filter = {
    must: [{ key: 'metadata.project', match: { value: project } }]
  };
}

return [{ json: body }];

const results = $input.first().json.result || [];
const trigger = $('Execute Workflow Trigger').first().json;

if (results.length === 0) {
  return [{ json: { output: `No relevant results found in project files for: "${trigger.query}"` } }];
}

const formatted = results.map((r, i) => {
  const m = r.payload?.metadata || {};
  const content = r.payload?.content || '';
  const lines = m.loc?.lines ? ` lines ${m.loc.lines.from}–${m.loc.lines.to}` : '';
  const score = (r.score * 100).toFixed(0);
  const summary = m.summary ? `// ${m.summary}\n` : '';
  return `[${i + 1}] ${m.filepath}${lines} (score: ${score}%)\n\`\`\`${m.filetype || ''}\n${summary}${content}\n\`\`\``;
}).join('\n\n');

return [{ json: { output: `Project RAG search: "${trigger.query}" — ${results.length} result(s)\n\n${formatted}` } }];
